import java.util.*;

class Solution {
    public String decodeString(String s) {
        Deque<StringBuilder> texts = new ArrayDeque<>();  // text before each '['
        Deque<Integer> counts = new ArrayDeque<>();       // repeat count for each '['
        StringBuilder cur = new StringBuilder();
        int num = 0;
        for (char c : s.toCharArray()) {
            if (Character.isDigit(c)) {
                num = num * 10 + (c - '0');
            } else if (c == '[') {
                texts.push(cur); counts.push(num);
                cur = new StringBuilder(); num = 0;
            } else if (c == ']') {
                StringBuilder prev = texts.pop();
                int k = counts.pop();
                for (int i = 0; i < k; i++) prev.append(cur);  // prev + cur * k
                cur = prev;
            } else {
                cur.append(c);
            }
        }
        return cur.toString();
    }
}

