class Solution:
    def decodeString(self, s: str) -> str:
        st = []; cur = ""; num = 0
        for c in s:
            if c.isdigit(): num = num * 10 + int(c)
            elif c == "[": st.append((cur, num)); cur, num = "", 0
            elif c == "]":
                prev, k = st.pop(); cur = prev + cur * k
            else: cur += c
        return cur

