function decodeString(s) {
  let i = 0;
  const parse = () => {
    let out = "";
    while (i < s.length && s[i] !== "]") {
      if (/[0-9]/.test(s[i])) { let k = 0; while (/[0-9]/.test(s[i])) k = k * 10 + Number(s[i++]); i++; const inner = parse(); i++; out += inner.repeat(k); }
      else out += s[i++];
    }
    return out;
  };
  return parse();
}
